  "Shared parallel worker count for scan/import and thumbnail creation jobs.": "Spoločný počet paralelných pracovníkov pre sken/import a vytváranie náhľadov.",
  "Show restaurants, fuel stations, hotels and similar places inside the map. Geoapify and Mapbox need an API key configured by the admin in the Admin panel → Maps. Overpass is free and requires no key.": "Zobrazuje reštaurácie, čerpacie stanice, hotely a podobné miesta na mape. Geoapify a Mapbox vyžadujú API kľúč nakonfigurovaný administrátorom v administrácii → Mapy. Overpass je zadarmo a kľúč nevyžaduje.",
  "Show travel-order numbers along each trajectory": "Zobrazovať čísla poradia cestovania pozdĺž každej trajektórie",
  "Shown while a thumbnail has not been generated yet, so you can see which items are not covered. You can pick a different picture for images, videos, and folders.": "Zobrazuje sa, kým nebol vygenerovaný náhľad, aby ste videli, ktoré položky nie sú pokryté. Pre obrázky, videá a priečinky môžete vybrať iný obrázok.",
