  "The map page lets each user pick a POI source per theme in their own user settings:": "Stránka mapy umožňuje každému používateľovi vybrať zdroj POI pre každý motív vo vlastnom nastavení:",
  "The optional gateway container is not enabled in this deployment, so the app serves plain HTTP only. To make HTTPS available, set": "Volitelný kontajner brány nie je v tomto nasadení povolený, takže aplikácia obsluhuje len obyčajné HTTP. Ak chcete HTTPS, nastavte",
  "This is the first startup. Create the account that will manage users, libraries, and access.": "Toto je prvé spustenie. Vytvorte účet, ktorý bude spravovať používateľov, knižnice a prístup.",
  "This media is no longer available in the library. It may have been moved or removed from disk, or this link is stale after a rescan.": "Toto médium už nie je v knižnici dostupné. Mohlo byť presunuté alebo odstránené z disku, alebo je tento odkaz po preskenovaní neaktuálny.",
  "This reset link is missing its token.": "Tomuto odkazu na obnovenie chýba jeho token.",
  "Thumbnails are capped by max count and never closer than the minimum interval.": "Náhľady sú obmedzené maximálnym počtom a nikdy nie sú bližšie ako minimálny interval.",
