function uaItemCount(n:number):string {
  if (n % 10 === 1 && n % 100 !== 11) return `${n} елемент`;
  if (n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20)) return `${n} елементи`;
  return `${n} елементів`;
}
function plItemCount(n:number):string {
  if (n === 1) return `${n} element`;
  if (n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) return `${n} elementy`;
  return `${n} elementów`;
}
function cheItemCount(n:number):string {
  if (n === 1) return `${n} položka`;
  if (n >= 2 && n <= 4) return `${n} položky`;
  return `${n} položek`;
}
function sloItemCount(n:number):string {
  if (n === 1) return `${n} položka`;
  if (n >= 2 && n <= 4) return `${n} položky`;
  return `${n} položiek`;
}

